class Solution {
public:
    long long zeroFilledSubarray(vector<int>& nums) {
        long long ans = 0;
        int consec = 0;
        for (int x : nums) {
            if (x == 0) {
                ++consec;
                ans += consec;
            } else {
                consec = 0;
            }
        }
        return ans;
    }
};
